--###############
--## MONITORS ###
--###############

-- See https://wiki.hyprland.org/Configuring/Monitors/
hl.monitor({
	output = "",
	mode = "preferred",
	position = "auto",
	scale = "1",
})

hl.monitor({
	output = "HDMI-A-1",
	mode = "1920x1080@60",
	position = "1920x0",
	scale = "1",
	-- mirror = "eDP-1",
})

--##################
--## MY PROGRAMS ###
--##################

-- See https://wiki.hyprland.org/Configuring/Keywords/

-- Set programs that you use
local terminal = "kitty"
local fileManager = "thunar"
local menu = "~/.config/hypr/scripts/wofi.sh"

--################
--## AUTOSTART ###
--################

hl.on("hyprland.start", function()
	hl.exec_cmd("uwsm app -- nm-applet &")
	hl.exec_cmd("uwsm app -- awww-daemon & waybar")
	hl.exec_cmd("zen-browser")
	hl.exec_cmd("uwsm app -- swaync")
	hl.exec_cmd("uwsm app -- systemctl --user start hyprpolkitagent")
	hl.exec_cmd("uwsm app -- udiskie &")
	hl.exec_cmd("discord")
	hl.exec_cmd("deezer-desktop")
	hl.exec_cmd("uwsm app -- sleep 5 && nm-applet --indicator")
	hl.exec_cmd("hyprsunset -t 2500")

	-- hl.exec_cmd("uwsm app -- wl-paste --type text --watch cliphist store #Stores only text data & uwsm app -- wl-paste --type image --watch cliphist store #Stores only image data")
	hl.exec_cmd("~/.config/hypr/scripts/changeConfig.sh")
end)


