--####################
--## LOOK AND FEEL ###
--####################

-- Refer to https://wiki.hyprland.org/Configuring/Variables/

-- https://wiki.hyprland.org/Configuring/Variables/#general

hl.curve("wind", { type = "bezier", points = { { 0.05, 0.9 }, { 0.1, 1.05 } } })
hl.curve("winIn", { type = "bezier", points = { { 0.1, 1.1 }, { 0.1, 1.1 } } })
hl.curve("winOut", { type = "bezier", points = { { 0.3, -0.3 }, { 0, 1 } } })
hl.curve("liner", { type = "bezier", points = { { 1, 1 }, { 1, 1 } } })
hl.animation({
	leaf = "windows",
	enabled = true,
	speed = 6,
	bezier = "wind",
	style = "slide",
})
hl.animation({
	leaf = "windowsOut",
	enabled = true,
	speed = 5,
	bezier = "winOut",
	style = "slide",
})
hl.animation({
	leaf = "border",
	enabled = true,
	speed = 1,
	bezier = "liner",
})
hl.animation({
	leaf = "borderangle",
	enabled = true,
	speed = 100,
	bezier = "liner",
	style = "loop",
})
hl.animation({
	leaf = "fade",
	enabled = true,
	speed = 7,
	bezier = "default",
})
hl.animation({
	leaf = "workspaces",
	enabled = true,
	speed = 5,
	bezier = "default",
})

hl.config({
	general = {
		gaps_in = 2,
		gaps_out = 5,
		border_size = 2,
		col = {
